import React, { useState, useEffect } from "react";
import {
  Truck,
  Users,
  Clock,
  DollarSign,
  LogOut,
  User,
  CreditCard,
  List,
  Menu,
  X,
} from "lucide-react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

function AdminDashboard() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [stats, setStats] = useState({
    totalOrders: 0,
    todayAmount: 0,
    yesterdayAmount: 0,
  });
  const [orders, setOrders] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("admintoken");
    const user = JSON.parse(localStorage.getItem("user") || "{}");

    if (!token || !user.is_admin) {
      navigate("/login");
      return;
    }

    fetchPayments(token);
  }, [navigate]);

  const fetchPayments = async (token) => {
    try {
      const response = await axios.get("http://localhost:4000/admin/payments", {
        headers: { Authorization: `Bearer ${token}` },
      });

      const allPayments = response.data;

      const today = new Date().toISOString().split("T")[0];
      const yesterday = new Date(Date.now() - 86400000)
        .toISOString()
        .split("T")[0];

      const todayPayments = allPayments.filter(
        (p) => p.created_at.split("T")[0] === today
      );
      const yesterdayPayments = allPayments.filter(
        (p) => p.created_at.split("T")[0] === yesterday
      );

      const calcAmount = (arr) =>
        arr.reduce((sum, val) => sum + Number(val.amount), 0);

      setStats({
        totalOrders: allPayments.length,
        todayAmount: calcAmount(todayPayments),
        yesterdayAmount: calcAmount(yesterdayPayments),
      });

      setOrders(allPayments.slice(0, 5)); // show only recent 5 orders
    } catch (err) {
      console.error("Dashboard Fetch Error:", err);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("admintoken");
    localStorage.removeItem("user");
    navigate("/login");
  };

  const displayStats = [
    {
      title: "Total Orders",
      value: stats.totalOrders,
      icon: <Truck size={28} />,
      color: "#2563eb",
    },
    {
      title: "Today Revenue",
      value: `₹${stats.todayAmount}`,
      icon: <DollarSign size={28} />,
      color: "#16a34a",
    },
    {
      title: "Yesterday Revenue",
      value: `₹${stats.yesterdayAmount}`,
      icon: <Clock size={28} />,
      color: "#f59e0b",
    },
    {
      title: "Active Partners",
      value: "520",
      icon: <Users size={28} />,
      color: "#dc2626",
    },
  ];

  return (
    <div style={pageStyle}>
      <header style={headerStyle}>
        <h2 style={logoStyle}>🚚 Admin Dashboard</h2>

        <nav className="desktop-nav" style={navStyle}>
          <a href="/admin-orders" style={navLink}>
            <List size={18} /> Orders
          </a>
          <a href="/admin-payments" style={navLink}>
            <CreditCard size={18} /> Payments
          </a>
          <a href="/admin-profile" style={navLink}>
            <User size={18} /> Profile
          </a>
          <button onClick={handleLogout} style={logoutBtn}>
            <LogOut size={18} /> Logout
          </button>
        </nav>

        <button
          className="menu-btn"
          onClick={() => setMenuOpen(!menuOpen)}
          style={menuBtn}
        >
          {menuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </header>

      {menuOpen && (
        <div style={mobileMenu}>
          <a href="/admin-orders" style={mobileLink}>
            <List size={18} /> Orders
          </a>
          <a href="/admin-payments" style={mobileLink}>
            <CreditCard size={18} /> Payments
          </a>
          <a href="/admin-profile" style={mobileLink}>
            <User size={18} /> Profile
          </a>
          <button onClick={handleLogout} style={mobileLink}>
            <LogOut size={18} /> Logout
          </button>
        </div>
      )}

      <h1 style={headingStyle}>📊 Overview</h1>

      <div style={statsGrid} className="stats-grid">
        {displayStats.map((stat, i) => (
          <div
            key={i}
            style={{ ...statCard, borderTop: `5px solid ${stat.color}` }}
            className="stat-card"
          >
            <div style={{ color: stat.color, marginBottom: "0.5rem" }}>
              {stat.icon}
            </div>
            <h3 style={statTitle}>{stat.title}</h3>
            <p style={statValue}>{stat.value}</p>
          </div>
        ))}
      </div>

      <div style={ordersContainer}>
        <h2 style={subHeading}>Recent Paid Orders</h2>
        <div style={{ overflowX: "auto" }}>
          <table style={tableStyle}>
            <thead>
              <tr>
                <th style={thStyle}>Order ID</th>
                <th style={thStyle}>Customer</th>
                <th style={thStyle}>Email</th>
                <th style={thStyle}>Amount</th>
                <th style={thStyle}>Date</th>
              </tr>
            </thead>
            <tbody>
              {orders.map((item) => (
                <tr key={item.order_id} style={rowHover}>
                  <td style={tdStyle}>{item.order_id}</td>
                  <td style={tdStyle}>{item.customer_name}</td>
                  <td style={tdStyle}>{item.customer_email}</td>
                  <td style={tdStyle}>₹{item.amount}</td>
                  <td style={tdStyle}>
                    {new Date(item.created_at).toLocaleString()}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <style>{`
        @media (max-width: 768px) {
          .desktop-nav { display: none; }
          .menu-btn { display: block !important; }
          .stats-grid { grid-template-columns: 1fr !important; }
          table { font-size: 0.85rem !important; }
        }
        .stat-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 8px 18px rgba(0,0,0,0.12);
          transition: all 0.3s ease;
        }
        tr:hover { background-color: #f9fafb; }
      `}</style>
    </div>
  );
